S = "Hakeem Force Academy"
QS = [
(S, "On which prophet was the Torah (Taurat) revealed?", ["Hazrat Isa (AS)", "Hazrat Musa (AS)", "Hazrat Dawud (AS)", "Hazrat Ibrahim (AS)"], 1, "The Torah was revealed on Hazrat Musa (AS) for the Bani Israil.", "The Zaboor was revealed on Hazrat Dawud (AS), the Injeel on Hazrat Isa (AS) and the Quran on Prophet Muhammad (PBUH).", 1),
(S, "On which river is the Mirani Dam built?", ["Dasht River", "Hub River", "Indus River", "Zhob River"], 0, "Mirani Dam is built on the Dasht River in Kech district of Balochistan, near Turbat.", "It was completed in 2006 mainly for irrigation and flood control in Makran.", 1),
(S, "On which river is Sukkur Barrage built?", ["Jhelum River", "Chenab River", "Indus River", "Ravi River"], 2, "Sukkur Barrage was built across the Indus River at Sukkur in Sindh.", "It was opened in 1932 and feeds seven major canals.", 1),
(S, "On which river is Tarbela Dam built?", ["Jhelum River", "Indus River", "Kabul River", "Chenab River"], 1, "Tarbela Dam is an earth-filled dam on the Indus River in Haripur district, Khyber Pakhtunkhwa.", "It is one of the largest earth-filled dams in the world, completed in 1974.", 1),
(S, "On whom was the Zaboor (Psalms) revealed?", ["Hazrat Musa (AS)", "Hazrat Isa (AS)", "Hazrat Sulaiman (AS)", "Hazrat Dawud (AS)"], 3, "The Zaboor was revealed on Hazrat Dawud (AS).", "Hazrat Dawud (AS) was also a king, and his son Hazrat Sulaiman (AS) was a prophet too.", 1),
(S, "Pakistan is a gateway to which region?", ["Central Asia", "Southeast Asia", "East Asia", "Northern Europe"], 0, "Pakistan lies between South Asia, Central Asia and the Arabian Sea, so its ports and routes give Central Asia access to the sea.", "Gwadar Port is promoted as a trade outlet for landlocked Central Asian states.", 1),
(S, "Pakistan is located in which continent?", ["Africa", "Europe", "Australia", "Asia"], 3, "Pakistan lies in South Asia, part of the continent of Asia.", "Pakistan borders Afghanistan, China, India and Iran.", 1),
(S, "Pakistan won the 2017 ICC Champions Trophy final against which team?", ["India", "England", "Sri Lanka", "Australia"], 0, "Pakistan beat India by 180 runs in the final at The Oval, London, on 18 June 2017.", "Sarfraz Ahmed captained Pakistan and Fakhar Zaman scored 114 in the final.", 1),
(S, "Who started Pakistan's biggest ambulance service?", ["Abdul Sattar Edhi", "Ramzan Chhipa", "Dr Adeeb Rizvi", "Hakim Muhammad Said"], 0, "Abdul Sattar Edhi founded the Edhi Foundation, which runs Pakistan's largest ambulance network.", "Edhi is known as the Angel of Mercy and died in 2016.", 1),
(S, "Petrol is a mixture of what?", ["Hydrocarbons", "Alcohols only", "Metal salts", "Carbon dioxide and water"], 0, "Petrol is a mixture of many liquid hydrocarbons obtained from crude oil.", "Its octane number measures how well it resists knocking in an engine.", 1),
(S, "Ping pong is another name for which game?", ["Badminton", "Squash", "Table tennis", "Lawn tennis"], 2, "Ping pong is the popular name for table tennis.", "Table tennis has been an Olympic sport since 1988.", 1),
(S, "Pour le Merite is an award of which country?", ["Austria", "France", "Germany", "Italy"], 2, "Pour le Merite is a Prussian and German order of merit, first founded in 1740 by Frederick the Great.", "In WWI the Blue Max was the nickname for its military class.", 1),
(S, "In which constitution of Pakistan was the presidential form of government adopted?", ["Constitution of 1956", "Constitution of 1962", "Government of India Act 1935", "Original Constitution of 1973"], 1, "The 1962 constitution given by Ayub Khan established a presidential system with a strong president.", "The 1956 and 1973 constitutions set up a parliamentary system.", 1),
(S, "Panja Sahib at Hassan Abdal is a sacred place of which religion?", ["Buddhism", "Hinduism", "Sikhism", "Christianity"], 2, "Gurdwara Panja Sahib at Hassan Abdal is holy to Sikhs, who believe Guru Nanak's handprint is on a rock there.", "Hassan Abdal is in Attock district, Punjab.", 1),
(S, "Which countries does the 38th parallel divide?", ["China and Russia", "North Korea and South Korea", "Japan and South Korea", "Vietnam and Laos"], 1, "The 38th parallel north was the dividing line between North and South Korea after 1945.", "The present border, the Demilitarized Zone, was set by the 1953 armistice and runs near the 38th parallel.", 1),
(S, "Rooh Ullah (Ruhullah) is the title of which prophet?", ["Hazrat Isa (AS)", "Hazrat Musa (AS)", "Hazrat Yahya (AS)", "Hazrat Yusuf (AS)"], 0, "Hazrat Isa (AS) is called Ruhullah, the Spirit of Allah, because he was born by Allah's command without a father.", "Hazrat Musa (AS) is called Kalimullah and Hazrat Ibrahim (AS) Khalilullah.", 2),
(S, "Rubber is obtained from which tree?", ["Rubber tree (Hevea brasiliensis)", "Teak tree", "Eucalyptus", "Deodar"], 0, "Natural rubber is made from latex tapped from the rubber tree, Hevea brasiliensis.", "Malaysia, Thailand and Indonesia are leading rubber producers.", 1),
(S, "Ruh-ul-Qudus is the title of which angel?", ["Hazrat Mikail (AS)", "Hazrat Israfil (AS)", "Hazrat Jibreel (AS)", "Hazrat Izrail (AS)"], 2, "Ruh-ul-Qudus (the Holy Spirit) is a title of the angel Hazrat Jibreel (AS), who brought revelation.", "Hazrat Jibreel (AS) is also called Ameen.", 1),
(S, "Against which country did Sachin Tendulkar score his 100th international century?", ["Pakistan", "Sri Lanka", "Bangladesh", "Australia"], 2, "Tendulkar scored his 100th international century (114) against Bangladesh in the Asia Cup at Mirpur on 16 March 2012.", "He is the only batter with 100 international centuries.", 1),
(S, "In which month is Shab-e-Qadr (Laylatul Qadr)?", ["Rajab", "Shaban", "Ramadan", "Muharram"], 2, "Laylatul Qadr falls in Ramadan, most likely on an odd night of the last ten days.", "The Quran was first revealed on this night, and Surah Al-Qadr describes it as better than a thousand months.", 1),
(S, "Complete the sentence: She said that she ___ to know.", ["wants", "wanted", "want", "is wanting"], 1, "In reported speech with the past tense verb said, the verb shifts to the past, so wanted is used.", "This shifting of tense is called backshift.", 1),
(S, "Sound travels in the form of what?", ["Electromagnetic waves", "Mechanical waves", "Light rays", "Radio waves"], 1, "Sound is a mechanical (longitudinal) wave that needs a medium such as air to travel.", "Sound cannot travel through a vacuum.", 1),
(S, "Stainless steel is an example of what?", ["Compound", "Pure element", "Alloy", "Mixture of gases"], 2, "Stainless steel is an alloy of iron with chromium and often nickel.", "Chromium of at least about 10.5 percent makes it resist rust.", 1),
(S, "Which country mediated the Tashkent Declaration of 1966 between Pakistan and India?", ["United States", "Soviet Union", "China", "United Kingdom"], 1, "The Soviet Union under Premier Alexei Kosygin mediated the Tashkent Declaration in January 1966.", "Indian Prime Minister Lal Bahadur Shastri died in Tashkent soon after signing.", 1),
(S, "The Thar desert of Sindh is rich in which mineral resource?", ["Coal", "Gold", "Bauxite", "Uranium"], 0, "Thar has one of the world's largest lignite coal reserves, about 175 billion tonnes.", "Thar coal is being used for power generation at Islamkot.", 1),
]
